report_styles:
@import "/assets/global/base.css";

:root {
    /* The conventional CVSS ramp. A reader knows what an orange High means;
       the house palette does not get to repaint that. */
    --color-risk-critical: #E8002B;
    --color-risk-high: #FF9300;
    --color-risk-medium: #FFC400;
    --color-risk-low: #4285F5;
    --color-risk-info: #00AE51;

    /* AnNIXion */
    --annixion-red: #FF0033;
    --annixion-ground: #0E0F13;
    --annixion-surface: #14171D;
    --annixion-rule: #2E323D;
    --annixion-muted: #5C6474;
    --annixion-ink: #14171D;
}

@page {
    size: A4 portrait;
    margin: 32mm 18mm 24mm 18mm;
}

/* The cover is a named page: full bleed, no running header or footer. The
   page background is what paints to the edge — an element background stops
   at the margin box. */
@page page-cover {
    margin: 0;
    background-color: var(--annixion-ground);
    @top-left-corner { content: none !important; }
    @top-left { content: none !important; }
    @top-center { content: none !important; }
    @top-right { content: none !important; }
    @top-right-corner { content: none !important; }
    @bottom-left-corner { content: none !important; }
    @bottom-left { content: none !important; }
    @bottom-center { content: none !important; }
    @bottom-right { content: none !important; }
    @bottom-right-corner { content: none !important; }
    @top-left-corner { content: none !important; }
    @top-right-corner { content: none !important; }
    @bottom-left-corner { content: none !important; }
}

html {
    font-family: "Noto Sans", sans-serif;
    font-size: 10pt;
    color: var(--annixion-ink);
    -weasy-hyphens: auto;
}

p { text-align: justify; text-align-last: start; }
a { color: var(--annixion-red); text-decoration: none; border-bottom: 0.5pt solid var(--annixion-red); }

/* ── Headings: a red rule above the number, labels in mono ─────────────── */
h1, h2, h3, h4, h5, h6 { font-family: "JetBrains Mono", "Noto Sans Mono", monospace; color: var(--annixion-ink); font-weight: 700; }
h1 {
    font-size: 15pt;
    border-top: 2pt solid var(--annixion-red);
    padding-top: 3mm;
    margin-top: 8mm;
    letter-spacing: -0.02em;
}
h2 { font-size: 12pt; margin-top: 6mm; }
h3 { font-size: 10.5pt; color: #3A4050; margin-top: 4mm; }
h4 { font-size: 10pt; color: var(--annixion-muted); }

/* ── Page furniture ────────────────────────────────────────────────────── */
/* Each piece is pulled out of the flow and placed in a page margin box. The
   borders on the boxes are what draw the rules across the page. */
#header-left { position: running(header-left); }
#header-right { position: running(header-right); }
#footer-left { position: running(footer-left); }
#footer-center { position: running(footer-center); }
#footer-right { position: running(footer-right); }

@page {
    --furniture: "JetBrains Mono", "Noto Sans Mono", monospace;

    @top-left {
        content: element(header-left);
        white-space: nowrap;
        font-family: var(--furniture);
        font-size: 7pt;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: #5C6474;
        vertical-align: bottom;
        padding-bottom: 2mm;
        border-bottom: 0.5pt solid #2E323D;
    }
    @top-right {
        content: element(header-right);
        font-family: var(--furniture);
        font-size: 7pt;
        letter-spacing: 0.1em;
        color: #5C6474;
        vertical-align: bottom;
        text-align: right;
        padding-bottom: 2mm;
        border-bottom: 0.5pt solid #2E323D;
    }
    @top-center { content: " "; border-bottom: 0.5pt solid #2E323D; }
    @top-left-corner { content: " "; border-bottom: 0.5pt solid #2E323D; }
    @top-right-corner { content: " "; border-bottom: 0.5pt solid #2E323D; }

    @bottom-left {
        content: element(footer-left);
        font-family: var(--furniture);
        font-size: 7pt;
        letter-spacing: 0.1em;
        color: #FF0033;
        vertical-align: top;
        padding-top: 2mm;
        border-top: 0.5pt solid #2E323D;
    }
    @bottom-center {
        content: element(footer-center);
        font-family: var(--furniture);
        font-size: 7pt;
        letter-spacing: 0.06em;
        color: #5C6474;
        vertical-align: top;
        text-align: center;
        padding-top: 2mm;
        border-top: 0.5pt solid #2E323D;
    }
    @bottom-right {
        content: counter(page) " / " counter(pages);
        font-family: var(--furniture);
        font-size: 7pt;
        color: #5C6474;
        vertical-align: top;
        text-align: right;
        padding-top: 2mm;
        border-top: 0.5pt solid #2E323D;
    }
    @bottom-left-corner { content: " "; border-top: 0.5pt solid #2E323D; }
    @bottom-right-corner { content: " "; border-top: 0.5pt solid #2E323D; }
}

#header-mark { display: inline-block; height: 3.5mm; width: 3.5mm; margin-right: 1.5mm; }
#header-mark svg { width: 3.5mm; height: 3.5mm; display: inline-block; vertical-align: middle; }

/* ── Cover ─────────────────────────────────────────────────────────────── */
/* This is what binds the section to the named page above; without it the
   cover inherits the body page and keeps the header, footer and margins. */
#page-cover { page: page-cover; }

#page-cover {
    background-color: var(--annixion-ground);
    color: #DFE4EA;
    height: 297mm;
    padding: 28mm 22mm;
    box-sizing: border-box;
    position: relative;
}
#page-cover-mark { display: block; width: 24mm; height: 24mm; }
#page-cover-mark svg { width: 24mm; height: 24mm; display: block; }
#header-mark svg { width: 4mm; height: 4mm; display: inline-block; vertical-align: middle; }
#page-cover-wordmark {
    font-family: "JetBrains Mono", monospace;
    font-size: 13pt;
    letter-spacing: 0.42em;
    text-transform: uppercase;
    margin-top: 6mm;
    color: #DFE4EA;
}
#page-cover-rule { width: 32mm; border-top: 2pt solid var(--annixion-red); margin: 10mm 0; }
#page-cover-title {
    font-family: "JetBrains Mono", monospace;
    font-size: 26pt;
    line-height: 1.15;
    letter-spacing: -0.03em;
    font-weight: 700;
    color: #FFFFFF;
    margin: 0;
    border: none;
    padding: 0;
}
#page-cover-subtitle { font-size: 12pt; color: var(--annixion-red); margin-top: 4mm; font-family: "JetBrains Mono", monospace; letter-spacing: 0.08em; }
#page-cover-meta {
    position: absolute;
    bottom: 28mm;
    left: 22mm;
    right: 22mm;
    font-size: 9pt;
    border-top: 0.5pt solid var(--annixion-rule);
    padding-top: 5mm;
}
#page-cover-meta table { width: 100%; border: none; }
#page-cover-meta tr td, #page-cover-meta tr:nth-child(even) td {
    border: none;
    padding: 1mm 0;
    color: #DFE4EA;
    background: none;
}
#page-cover-meta td.k {
    font-family: "JetBrains Mono", monospace;
    font-size: 7.5pt;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--annixion-muted);
    width: 38mm;
}
#page-cover-classification {
    position: absolute;
    top: 14mm;
    right: 22mm;
    font-family: "JetBrains Mono", monospace;
    font-size: 8pt;
    letter-spacing: 0.18em;
    color: var(--annixion-red);
    border: 0.75pt solid var(--annixion-red);
    padding: 1.5mm 3mm;
}

/* ── Table of contents ─────────────────────────────────────────────────── */
#toc li { list-style: none; margin: 1.2mm 0; }
#toc .toc-level1 { font-weight: 700; font-family: "JetBrains Mono", monospace; font-size: 9.5pt; }
#toc .toc-level2 { margin-left: 6mm; }
#toc .toc-level3 { margin-left: 12mm; color: var(--annixion-muted); }
#toc a { border: none; color: var(--annixion-ink); }
#toc .ref-page::before { content: target-counter(attr(href), page); float: right; font-family: "JetBrains Mono", monospace; }

/* ── Tables ────────────────────────────────────────────────────────────── */
table { width: 100%; border-collapse: collapse; font-size: 9pt; }
th {
    background-color: var(--annixion-surface);
    color: #DFE4EA;
    font-family: "JetBrains Mono", monospace;
    font-size: 7.5pt;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    text-align: left;
    padding: 2mm;
}
td { border-bottom: 0.5pt solid #D8DCE3; padding: 2mm; vertical-align: top; }
tr:nth-child(even) td { background-color: #F6F7F9; }

/* ── Findings ──────────────────────────────────────────────────────────── */
.finding-head {
    border-top: 2pt solid var(--annixion-red);
    padding-top: 3mm;
    margin-top: 8mm;
}
.finding-meta { width: 100%; margin: 3mm 0 5mm 0; font-size: 8.5pt; }
.finding-meta td { border: none; padding: 1mm 2mm 1mm 0; }
.finding-meta td.k {
    font-family: "JetBrains Mono", monospace;
    font-size: 7.5pt;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--annixion-muted);
    width: 30mm;
}
.risk-pill {
    font-family: "JetBrains Mono", monospace;
    font-size: 8pt;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #FFFFFF;
    padding: 0.8mm 2.5mm;
}
.risk-bg-critical { background-color: var(--color-risk-critical); color: #FFFFFF; }
.risk-bg-high { background-color: var(--color-risk-high); color: #14171D; }
.risk-bg-medium { background-color: var(--color-risk-medium); color: #14171D; }
.risk-bg-low { background-color: var(--color-risk-low); color: #FFFFFF; }
.risk-bg-info { background-color: var(--color-risk-info); color: #FFFFFF; }

/* ── Callouts ──────────────────────────────────────────────────────────── */
#page-cover a { border: none; color: #DFE4EA; }

.note {
    border-left: 2pt solid var(--annixion-red);
    background-color: #F6F7F9;
    padding: 3mm 4mm;
    margin: 4mm 0;
}
.label {
    font-family: "JetBrains Mono", monospace;
    font-size: 7.5pt;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--annixion-muted);
}
pre, code { font-family: "JetBrains Mono", "Noto Sans Mono", monospace; font-size: 8.5pt; }
pre { background-color: var(--annixion-surface); color: #DFE4EA; padding: 3mm; border-radius: 0; }
blockquote { border-left: 2pt solid var(--annixion-rule); margin-left: 0; padding-left: 4mm; color: #3A4050; }
